package com.chargehub.app;
import com.chargehub.infrastructure.*;import com.chargehub.identity.Actor;import com.chargehub.station.*;import com.chargehub.benefit.BenefitService;import com.chargehub.charging.*;import com.chargehub.payment.PaymentService;import com.chargehub.reconcile.ReconciliationService;
import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.http.HttpStatus;import jakarta.servlet.http.HttpServletRequest;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;

@RestController
public class ApiController {
 private final StationService stations;private final BenefitService benefits;private final ChargeService orders;private final SessionService sessions;private final PaymentService payments;private final ReconciliationService reconcile;private final Idempotency idem;private final Outbox outbox;private final Hmac hmac;private final Db db;private final Clock clock;
 public ApiController(StationService stations,BenefitService benefits,ChargeService orders,SessionService sessions,PaymentService payments,ReconciliationService reconcile,Idempotency idem,Outbox outbox,Hmac hmac,Db db,Clock clock){this.stations=stations;this.benefits=benefits;this.orders=orders;this.sessions=sessions;this.payments=payments;this.reconcile=reconcile;this.idem=idem;this.outbox=outbox;this.hmac=hmac;this.db=db;this.clock=clock;}
 private Object ok(Object value){return ApiResponse.ok(value);}
 private Map<String,Object> write(String scope,String key,Map<String,Object> body,java.util.function.Supplier<Map<String,Object>> action){return idem.execute(Actor.id(),scope,key,body,action);}
 private static Long optionalId(Map<String,Object> b,String key){return b.get(key)==null?null:ChargeService.number(b,key);}
 private static int limit(int l){if(l<1||l>100)throw new BusinessException(400,"VALIDATION_ERROR","limit范围为1至100");return l;}
 private static Map<String,Object> empty(){return Map.of();}
 private static void only(Map<String,Object> b,String... fields){Set<String> keys=Set.of(fields);for(String k:b.keySet())if(!keys.contains(k))throw new BusinessException(400,"VALIDATION_ERROR","不支持的参数: "+k);}
 private static void booleanField(Map<String,Object> b,String name){if(!(b.get(name) instanceof Boolean))throw new BusinessException(400,"VALIDATION_ERROR",name+"必须是布尔值");}
 @GetMapping("/v1/stations") Object stations(@RequestParam(required=false) Long cursor,@RequestParam(defaultValue="20") int limit){return ok(stations.list(cursor,limit(limit)));}
 @GetMapping("/v1/me/benefits") Object benefits(){return ok(benefits.benefits(Actor.id()));}
 @GetMapping("/v1/coupon-templates") Object templates(@RequestParam(required=false) Long cursor,@RequestParam(defaultValue="20") int limit){return ok(benefits.templates(cursor,limit(limit)));}
 @GetMapping("/v1/me/coupons") Object coupons(@RequestParam(required=false) Long cursor,@RequestParam(defaultValue="20") int limit){return ok(benefits.coupons(Actor.id(),cursor,limit(limit)));}
 @PostMapping("/v1/coupon-templates/{id}/claims") Object claim(@PathVariable long id,@RequestHeader("Idempotency-Key") String key){return ok(write("claim/"+id,key,empty(),()->benefits.claim(Actor.id(),id)));}
 @PostMapping("/v1/charge-quotes") Object quote(@RequestBody Map<String,Object> b){
  only(b,"connectorId","estimatedEnergyWh","useMembership","couponId");booleanField(b,"useMembership");long wh=ChargeService.number(b,"estimatedEnergyWh");if(wh<1||wh>1_000_000)throw new BusinessException(400,"VALIDATION_ERROR","预计电量范围为1至1000000Wh");
  Map<String,Object> tariff=stations.tariff(ChargeService.number(b,"connectorId"),null),benefit=benefits.preview(Actor.id(),Boolean.TRUE.equals(b.get("useMembership")),optionalId(b,"couponId"));
  int minute=clock.instant().atZone(ZoneId.of(String.valueOf(tariff.get("timezone")))).getHour()*60+clock.instant().atZone(ZoneId.of(String.valueOf(tariff.get("timezone")))).getMinute();
  Map<String,Object> slot=((List<Map<String,Object>>)tariff.get("slots")).stream().filter(s->minute>=ChargeService.number(s,"startMinute")&&minute<ChargeService.number(s,"endMinute")).findFirst().orElseThrow();
  var a=BillingCalculator.calculate(List.of(new BillingCalculator.Segment(wh,(int)ChargeService.number(slot,"energyRateFenPerKwh"),(int)ChargeService.number(slot,"serviceRateFenPerKwh"))),Boolean.TRUE.equals(benefit.get("member")),(Long)benefit.get("couponThresholdFen"),(Long)benefit.get("couponDiscountFen"),10000);
  return ok(Map.of("estimated",true,"tariffVersion",tariff.get("tariffVersion"),"prepaidFen",10000,"amounts",a.amounts(),"expiresAt",clock.instant().plusSeconds(60).toString()));
 }
 @PostMapping("/v1/charge-orders") @ResponseStatus(HttpStatus.CREATED) Object create(@RequestBody Map<String,Object> b,@RequestHeader("Idempotency-Key") String key){only(b,"connectorId","expectedTariffVersion","useMembership","couponId");booleanField(b,"useMembership");return ok(write("orders.create",key,b,()->orders.create(Actor.id(),b)));}
 @GetMapping("/v1/charge-orders") Object orders(@RequestParam(required=false) Long cursor,@RequestParam(defaultValue="20") int limit){return ok(orders.list(Actor.id(),cursor,limit(limit)));}
 @GetMapping("/v1/charge-orders/{no}") Object order(@PathVariable String no){return ok(orders.owned(Actor.id(),no));}
 @PostMapping("/v1/charge-orders/{no}/payment") @ResponseStatus(HttpStatus.ACCEPTED) Object payment(@PathVariable String no,@RequestHeader("Idempotency-Key") String key){Map<String,Object> p=write("payment/"+no,key,empty(),()->orders.payment(Actor.id(),no));return ok(paymentView(p));}
 @PostMapping("/v1/charge-orders/{no}/cancel") @ResponseStatus(HttpStatus.ACCEPTED) Object cancel(@PathVariable String no,@RequestHeader("Idempotency-Key") String key){return ok(write("cancel/"+no,key,empty(),()->orders.cancel(Actor.id(),no)));}
 @PostMapping("/v1/charge-orders/{no}/stop") @ResponseStatus(HttpStatus.ACCEPTED) Object stop(@PathVariable String no,@RequestHeader("Idempotency-Key") String key){return ok(write("stop/"+no,key,empty(),()->orders.stop(Actor.id(),no)));}
 @GetMapping("/v1/charge-orders/{no}/bill") Object bill(@PathVariable String no){orders.owned(Actor.id(),no);Map<String,Object> b=sessions.bill(no);if(b==null)throw new BusinessException(409,"BILLING_DATA_INCOMPLETE","尚无完整正式账单");return ok(b);}
 @GetMapping("/v1/charge-orders/{no}/funds") Object funds(@PathVariable String no){Map<String,Object> o=orders.owned(Actor.id(),no);Map<String,Object> internal=payments.funds(no);Map<String,Object> p=(Map<String,Object>)internal.get("payment");Map<String,Object> b=db.one("SELECT payable_fen FROM charge_bill WHERE order_no=?",no);long capture=Db.num(p,"captured_fen"),refunded=Db.num(p,"refund_success_fen");Map<String,Object> f=new LinkedHashMap<>();f.put("orderNo",no);f.put("capturedFen",capture);f.put("refundReservedFen",Db.num(p,"refund_reserved_fen"));f.put("refundSuccessFen",refunded);f.put("netReceivedFen",capture-refunded);f.put("shortfallFen",Math.max(0,Db.num(b,"payable_fen")-capture));f.put("financialStatus",o.get("financial_status"));f.put("refunds",((List<Map<String,Object>>)internal.get("refunds")).stream().map(r->Map.of("refundNo",r.get("refundNo"),"status",r.get("status"),"amountFen",r.get("amountFen"),"reason",r.get("reason"))).toList());return ok(f);}
 @PostMapping("/integrations/payments/mock/notifications") Object notifyPay(HttpServletRequest request,@RequestBody byte[] raw){hmac.verify(request,raw,"payment");return ok(orders.notification(Json.read(new String(raw,StandardCharsets.UTF_8))));}
 @PostMapping("/integrations/devices/events") Object device(HttpServletRequest request,@RequestBody byte[] raw){hmac.verify(request,raw,"device");sessions.ingest(Json.read(new String(raw,StandardCharsets.UTF_8)));return ok(Map.of("accepted",true));}
 @PostMapping("/v1/admin/tariffs") @PreAuthorize("hasAnyRole('OPS','ADMIN')") Object tariff(@RequestBody Map<String,Object> b,@RequestHeader("Idempotency-Key") String key){return ok(write("tariffs.create",key,b,()->stations.createTariff(b)));}
 @PostMapping("/v1/admin/tariffs/{id}/publish") @PreAuthorize("hasAnyRole('OPS','ADMIN')") Object publish(@PathVariable long id,@RequestHeader("Idempotency-Key") String key){return ok(write("tariffs.publish/"+id,key,empty(),()->stations.publishTariff(id)));}
 @PostMapping("/v1/admin/coupon-templates") @PreAuthorize("hasAnyRole('OPS','ADMIN')") Object template(@RequestBody Map<String,Object> b,@RequestHeader("Idempotency-Key") String key){return ok(write("templates.create",key,b,()->benefits.createTemplate(b)));}
 @PostMapping("/v1/admin/coupon-templates/{id}/publish") @PreAuthorize("hasAnyRole('OPS','ADMIN')") Object publishTemplate(@PathVariable long id,@RequestHeader("Idempotency-Key") String key){return ok(write("templates.publish/"+id,key,empty(),()->benefits.publishTemplate(id)));}
 @PostMapping("/v1/admin/reconciliations") @PreAuthorize("hasAnyRole('FINANCE','ADMIN')") @ResponseStatus(HttpStatus.ACCEPTED) Object reconcile(@RequestParam MultipartFile file,@RequestParam String channel,@RequestParam String businessDate,@RequestParam String billType,@RequestParam String sourceTimezone,@RequestParam int versionNo,@RequestHeader("Idempotency-Key") String key)throws java.io.IOException{
  if(file.getSize()>10*1024*1024)throw new BusinessException(413,"FILE_TOO_LARGE","文件超过10MiB");String csv;try{csv=StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(file.getBytes())).toString();}catch(java.nio.charset.CharacterCodingException e){throw new BusinessException(400,"INVALID_CSV","CSV必须为UTF-8");}Map<String,Object> req=Map.of("channel",channel,"businessDate",businessDate,"billType",billType,"sourceTimezone",sourceTimezone,"versionNo",versionNo,"fileHash",Json.hash(csv));
  return ok(write("reconcile.import",key,req,()->{Map<String,Object> r=reconcile.importCsv(Actor.id(),channel,businessDate,billType,sourceTimezone,versionNo,csv,"财务导入渠道账单");Object nos=reconcile.diffOrderNos(Long.parseLong(String.valueOf(r.getOrDefault("batchId",r.get("id")))));if(nos instanceof List<?> list)for(Object no:list)db.update("UPDATE charge_order SET financial_status='DIFF',exception_code=COALESCE(exception_code,'RECONCILIATION_DIFFERENCE') WHERE order_no=?",no);return r;}));
 }
 @GetMapping("/v1/admin/reconciliation-items") @PreAuthorize("hasAnyRole('FINANCE','ADMIN')") Object diffs(@RequestParam(required=false) String cursor,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String status){return ok(reconcile.items(cursor,limit(limit),status));}
 @PostMapping("/v1/admin/refunds/{no}/retry") @PreAuthorize("hasAnyRole('FINANCE','ADMIN')") @ResponseStatus(HttpStatus.ACCEPTED) Object retry(@PathVariable String no,@RequestBody Map<String,Object> b,@RequestHeader("Idempotency-Key") String key){String reason=reason(b);return ok(write("refund.retry/"+no,key,b,()->{Map<String,Object> r=db.one("SELECT * FROM refund_order WHERE refund_no=?",no);if(r==null)throw new BusinessException(404,"NOT_FOUND","退款不存在");if("SUCCESS".equals(r.get("status")))return Map.of("resourceNo",no,"status","SUCCESS");if("FAILED_FINAL".equals(r.get("status")))throw new BusinessException(409,"REFUND_FINAL_REJECTION","渠道已最终拒绝，同一退款号需人工核实，不生成新退款");db.update("UPDATE refund_order SET next_query_at=UTC_TIMESTAMP(3) WHERE refund_no=?",no);db.update("INSERT INTO ops_audit(operator_id,action,target_type,target_no,reason,request_id) VALUES(?,'REFUND_RETRY','REFUND',?,?,?)",Actor.id(),no,reason,UUID.randomUUID().toString());return Map.of("resourceNo",no,"status","UNKNOWN");}));}
 @PostMapping("/v1/admin/outbox/{eventId}/replay") @PreAuthorize("hasRole('ADMIN')") Object replay(@PathVariable String eventId,@RequestBody Map<String,Object> b,@RequestHeader("Idempotency-Key") String key){String reason=reason(b);return ok(write("outbox.replay/"+eventId,key,b,()->outbox.replay(eventId,Actor.id(),reason)));}
 private Map<String,Object> paymentView(Map<String,Object> p){Map<String,Object> view=new LinkedHashMap<>();for(String key:List.of("payNo","orderNo","status","amountFen","currency"))view.put(key,p.get(key));view.put("checkoutUrl",p.get("checkoutUrl"));return view;}
 private String reason(Map<String,Object> b){only(b,"reason");String r=String.valueOf(b.getOrDefault("reason",""));if(r.length()<5||r.length()>255)throw new BusinessException(400,"VALIDATION_ERROR","操作原因需5至255字");return r;}
}
